import numpy as np
from sklearn import utils as U
from sklearn.utils import extmath as E, class_weight as CW, multiclass as MC
from sklearn.base import (BaseEstimator, ClassifierMixin, RegressorMixin, TransformerMixin, ClusterMixin,
                          clone, is_classifier, is_regressor, is_clusterer, get_params)

cw_bal = [1.6666666666666667, 1.1111111111111112, 0.6666666666666666]
sw_bal = [1.6666666666666667, 1.1111111111111112, 1.1111111111111112, 0.6666666666666666, 0.6666666666666666, 0.6666666666666666, 1.6666666666666667, 1.1111111111111112, 0.6666666666666666, 0.6666666666666666]
tot_bin = 'binary'
tot_mc = 'multiclass'
tot_cont = 'continuous'
tot_ml = 'multilabel-indicator'
ul = [1.0, 2.0, 3.0, 5.0]
rn = [1.1055415967851334, 2.6034165586355518, 1.49071198499986, 2.42670329642684, 3.0368111930481, 1.1055415967851334]
rn2 = [1.2222222222222223, 6.777777777777779, 2.2222222222222228, 5.88888888888889, 9.222222222222223, 1.2222222222222223]
smax = [0.14833709805949272, 0.2889212154417395, 0.5627416864987679, 0.3284389353424031, 0.639711694774154, 0.03184936988344292, 0.1483370980594927, 0.2889212154417395, 0.5627416864987679, 0.8720227775885223, 0.04341545764613438, 0.08456176476534343, 0.14833709805949272, 0.28892121544173943, 0.5627416864987679, 0.1483370980594927, 0.2889212154417395, 0.5627416864987679]
cart = [1.0, 3.0, 1.0, 4.0, 1.0, 5.0, 2.0, 3.0, 2.0, 4.0, 2.0, 5.0]
scs = [1.0, 3.0, 6.0, 10.0, 15.0]
wm = [3.0]
wmw = [2.1]
bat = [0.0, 3.0, 6.0, 9.0]
evs = [4.0, 7.0, 10.0]
rs = [5.0, 0.0, 3.0, 3.0, 7.0, 9.0, 3.0, 5.0, 2.0, 4.0]
sh = [7.0, 2.0, 1.0, 6.0, 0.0, 4.0, 3.0, 5.0]
rs_s = [3.0, 3.0, 1.0, 2.0, 8.0, 0.0]

def close(got, exp: List[float], rtol: float = 1e-12, atol: float = 1e-14) -> bool:
    g = np.asarray(got, dtype=float).ravel()
    if g.size != len(exp):
        print("size mismatch", g.size, len(exp))
        return False
    for i in range(len(exp)):
        e = exp[i]
        if np.isnan(e):
            if not np.isnan(g[i]):
                print("mismatch at", i, g[i], e)
                return False
        elif abs(g[i] - e) > atol + rtol * abs(e):
            print("mismatch at", i, g[i], e)
            return False
    return True


y = np.array([0, 1, 1, 2, 2, 2, 0, 1, 2, 2])
X = np.empty((6, 3))
for i in range(6):
    for j in range(3):
        X[i, j] = ((i * 7 + j * 13) % 11) / 3.0 - 1.0

@test
def t_utils():
    assert close(CW.compute_class_weight("balanced", classes=np.array([0, 1, 2]), y=y), cw_bal)
    assert close(CW.compute_sample_weight("balanced", y), sw_bal)
    assert MC.type_of_target(np.array([0, 1, 1])) == tot_bin and MC.type_of_target(y) == tot_mc
    assert MC.type_of_target(np.array([0.5, 1.5])) == tot_cont and MC.type_of_target(np.array([[0, 1], [1, 1]])) == tot_ml
    assert close(MC.unique_labels(np.array([3, 1]), np.array([2, 1, 5])), ul)
    assert close(E.row_norms(X), rn) and close(E.row_norms(X, squared=True), rn2)
    assert close(E.softmax(X), smax) and close(E.cartesian([np.array([1, 2]), np.array([3, 4, 5])]), cart)
    assert close(E.stable_cumsum(np.arange(1.0, 6.0)), scs)
    m, s = E.weighted_mode(np.array([1, 2, 2, 3, 3]), np.array([1.0, 1.0, 0.5, 2.0, 0.1]))
    assert close(m, wm) and close(s, wmw)
    assert close(np.array([b.start for b in U.gen_batches(10, 3)]), bat)
    assert close(np.array([b.stop for b in U.gen_even_slices(10, 3)]), evs)
    assert close(U.resample(np.arange(10), random_state=0), rs) and close(U.shuffle(np.arange(8), random_state=1), sh)
    assert close(U.resample(np.arange(10), y, n_samples=6, random_state=3, stratify=y)[0], rs_s)
    assert U.murmurhash3_32("hello", seed=3) == -685068171 and U.murmurhash3_32(42, positive=True) == 3160117731

class Toy(BaseEstimator, ClassifierMixin):
    alpha: float
    kind: str
    n_iter: Optional[int]
    coef_: np.ndarray[float, 1]

    def __init__(self, alpha: float = 1.0, kind: str = "a", n_iter: Optional[int] = None):
        self.alpha = alpha
        self.kind = kind
        self.n_iter = n_iter
        self.coef_ = np.zeros(0)

    def fit(self, X, y):
        self.coef_ = np.ones(X.shape[1]) * self.alpha
        return self

    def predict(self, X):
        return (X @ self.coef_ > 0).astype(int)

class ToyReg(BaseEstimator, RegressorMixin):
    w: float
    def __init__(self, w: float = 2.0):
        self.w = w
    def fit(self, X, y):
        return self
    def predict(self, X):
        return X[:, 0] * self.w

@test
def t_base():
    t = Toy(alpha=0.5, kind="b")
    assert repr(t) == "Toy(alpha=0.5, kind='b', n_iter=None)"
    p = t.get_params()
    assert len(p) == 3 and p["alpha"] == "0.5" and p["kind"] == "'b'"
    t.set_params(alpha=3.0, n_iter=5)
    assert t.alpha == 3.0 and get_params(t)["n_iter"] == "5"
    t.fit(X, y[:6])
    c = clone(t)
    assert c.alpha == 3.0 and c.kind == "b"
    yy = (X[:, 0] > 0).astype(int)
    from sklearn.metrics import accuracy_score, r2_score
    assert t.score(X, yy) == accuracy_score(yy, t.predict(X))
    r = ToyReg()
    assert r.score(X, X[:, 1]) == r2_score(X[:, 1], r.predict(X))
    assert is_classifier(t) and not is_regressor(t) and is_regressor(r) and not is_clusterer(r)

t_utils()
t_base()
